<template>
  <div class="layout-px-spacing">
    <ul class="navbar-nav flex-row mt-2">
      <li>
        <div class="page-header">
          <nav class="breadcrumb-one" aria-label="breadcrumb">
            <ol class="breadcrumb">
              <li class="breadcrumb-item"><a href="javascript:;">Producurement</a></li>
              <li class="breadcrumb-item active" aria-current="page">
                <span
                  >Good Received Notes / {{ local_orders ? "Local" : "General" }}</span
                >
              </li>
            </ol>
          </nav>
        </div>
      </li>
    </ul>

    <teleport to="#breadcrumb">
      <div class="flex-row ms-auto me-5">
        <span v-html="refreshButton(getGrns, loading_spinner)"></span>
      </div>
    </teleport>

    <h4 class="text-center">GOOD RECEIVED NOTES</h4>

    <div
      v-if="grn_cost > 0"
      class="badge rounded-pill bg-success text-white px-3 py-2 shadow-sm my-2"
      :class="
        selectedStatus === 'Received'
          ? 'bg-success'
          : selectedStatus === 'Partial Received'
          ? 'bg-secondary'
          : selectedStatus === 'Delayed'
          ? 'bg-danger'
          : 'bg-warning'
      "
    >
      Total Cost : {{ formatNumber(grn_cost) }}
    </div>

  <div class="d-flex mb-2 gap-2 align-items-center">
 <div class="ms-auto w-100">
    <div class="filter-container d-flex flex-wrap justify-content-end align-items-end gap-2">
    <div class="status-filter">
                <label class="form-label fw-semibold">Select Project</label>
                <multiselect
                    v-model="project"
                    :options="projects"
                    label="name"
                    placeholder="Select Project"
                    :searchable="true"
                    :multiple="false"
                    :allow-empty="true"
                />
            </div>
  
  <div class="status-filter">
    <label class="form-label mb-1">Status</label>
    <multiselect
      v-model="status"
      :options="statuses"
      placeholder="Select Status"
      label="name"
      :searchable="true"
      :multiple="false"
      :allow-empty="true"
      @select="handleStatusChange"
    />
  </div>

  <div class="date-filter">
    <label class="form-label mb-1">From Date</label>
    <input
      type="date"
      class="form-control"
      v-model="from_date"
    />
  </div>

  <div class="date-filter">
    <label class="form-label mb-1">To Date</label>
    <input
      type="date"
      class="form-control"
      v-model="to_date"
    />
  </div>

</div>


    <!-- Search and buttons -->
    <div class="d-flex me-4 mt-2 align-items-center justify-content-end gap-2 flex-wrap my-4">

    <input
        type="text"
        class="form-control"
        style="flex: 1 1 200px; max-width: 250px;"
        v-model="grn_no"
        placeholder="Search Grn No..."
      />

      <input
        type="text"
        class="form-control"
        style="flex: 1 1 200px; max-width: 250px;"
        v-model="lpo_no"
        placeholder="Search LPO No..."
      />

      <div class="btn-group">
        <!-- <button
          class="btn btn-dark text-nowrap me-1"
          @click="
            lpo_no = '';
            status = '';
            selectedStatus = 'all';
            from_date = '';
            to_date = '';
            getGrns();
          "
        >
          Fetch All
        </button> -->

        <div class="btn-group" role="group">
    <button class="btn btn-success me-2" @click="handlePrintReport()">
      <i class="bi bi-printer fs-4"></i>
    </button>
    <button class="btn btn-info" @click="handleExcelReport()">
      <i class="bi bi-file-earmark-spreadsheet  fs-4"></i>
    </button>
    </div>
      </div>

    </div>

  </div>
</div>

    <globalSearchField v-model:filterValue="filter" />

    <div v-if="loading_spinner" v-html="tableShimmer()"></div>

    <div v-else class="row layout-top-spacing">
      <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
        <div class="panel p-0">
          <div v-if="local_orders" class="custom-table table3">
            <v-client-table
              :data="localOrders"
              :columns="localOrderColumns"
              :options="table_option"
            >
              <template #status="props">
                <span class="badge inv-status" :class="'badge-' + props.row.status.color">
                  {{ props.row.status.name }}
                </span>
              </template>

              <template #actions="props">
                <a
                  href="javascript:;"
                  class="edit me-2"
                  @click="fillModal(props.row)"
                  data-bs-toggle="modal"
                  data-bs-target="#view_items"
                >
                  <i class="bi bi-pencil-square text-primary fs-4"></i>
                </a>
              </template>
            </v-client-table>
          </div>

          <div v-else class="custom-table table3">
            <v-client-table
              :data="filteredData"
              :columns="columns"
              :options="table_option"
            >
              <template #lpo_no="props">
                <router-link
                  :to="`/approval-chain/${props.row.approval_id}`"
                  class="text-primary"
                  >{{ props.row.lpo_no }}</router-link
                >
              </template>

              <template #status="props">
                <span class="badge inv-status" :class="'badge-' + props.row.status.class">
                  {{ props.row.status.key }}
                </span>
              </template>

              <template #delayed_count="props">
                <span v-if="props.row.status.key === 'Delayed'"
                  >{{ props.row.delayed_count }} days</span
                >
              </template>

              <template #actions="props">
                <a
                  href="javascript:void(0);"
                  class="text-secondary position-relative me-2"
                  @click="
                    fillModal(props.row);
                    noteModalRef.open(null, props.row.id);
                  "
                >
                  <i class="bi bi-journal-bookmark-fill fs-5"></i>
                  <span
                    v-if="props.row.logs_count > 0"
                    class="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger"
                    style="font-size: 9px; min-width: 16px; padding: 2px 4px"
                  >
                    {{ props.row.logs_count }}
                  </span>
                </a>

                <a
                  href="javascript:;"
                  class="edit"
                  @click="fillModal(props.row)"
                  data-bs-toggle="modal"
                  data-bs-target="#view_items"
                >
                  <i class="bi bi-pencil-square text-primary fs-5"></i>
                </a>
              </template>
            </v-client-table>
          </div>
        </div>
      </div>
    </div>

    <!-- Edit Grn Modal -->
    <div
      class="modal fade mymodal"
      id="view_items"
      data-bs-backdrop="false"
      tabindex="-1"
      role="dialog"
      aria-labelledby="editModalLabel"
      aria-hidden="true"
    >
      <div class="modal-dialog modal-fullscreen" role="document">
        <!-- Changed to modal-xl and added scrollable -->
        <div class="modal-content">
          <!-- Added min-height -->
          <div class="modal-header">
            <h5 class="modal-title" id="editModalLabel">GOODS RECEIVED LIST</h5>
            <button
              type="button"
              class="btn-close"
              data-bs-dismiss="modal"
              aria-label="Close"
              id="dismiss"
              @click="clearForm"
            ></button>
          </div>
          <div class="modal-body">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
              <div class="panel p-0">
                <div class="custom-table table3 table-responsive">
                  <table class="table table-bordered table-striped">
                    <thead>
                      <tr>
                        <th>GRN No</th>
                        <th>LPO No</th>
                        <th>Requester</th>
                        <th>Receiver</th>
                        <th>Date Created</th>
                        <th>Date Received</th>
                        <th>Project</th>
                        <th>Vendor</th>
                        <th>Cost</th>
                        <th>Status</th>
                        <th>Delay</th>
                        <th>Action</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr>
                        <td>{{ grn.id }}</td>
                        <td>{{ grn.lpo_no }}</td>
                        <td>{{ grn.requester }}</td>
                        <td>{{ grn.receiver }}</td>
                        <td>{{ grn.date }}</td>
                        <td>{{ grn.received_date }}</td>
                        <td>{{ grn.project }}</td>
                        <td>{{ grn.vendor ?? "No vendor" }}</td>
                        <td>{{ grn.cost }}</td>
                        <td>
                          <span
                            class="badge inv-status"
                            :class="'badge-' + grn.status?.class"
                          >
                            {{ grn.status?.key }}
                          </span>
                        </td>
                        <td>{{ grn.delay }}</td>
                        <td>
                          <a
                            v-if="user_permissions.includes('can_print_grn')"
                            href="javascript:void(0);"
                            @click="printGrn(grn, items)"
                            class="text-success me-2"
                          >
                            <i class="bi bi-printer fs-4"></i>
                          </a>
                          <a
                            href="javascript:void(0);"
                            class="text-secondary position-relative me-2"
                            @click.stop="noteModalRef.open('view_items', grn_id)"
                          >
                            <i class="bi bi-journal-bookmark-fill fs-4"></i>
                            <span
                              v-if="grn.logs_count > 0"
                              class="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger"
                              style="font-size: 9px; min-width: 16px; padding: 2px 4px"
                            >
                              {{ grn.logs_count }}
                            </span>
                          </a>
                        </td>
                      </tr>
                      <tr v-if="grn.briefing != null">
                        <td colspan="5">
                          <b> Brief Description : </b> {{ grn.briefing }}
                        </td>
                      </tr>
                      <tr v-if="grn.remarks">
                        <td colspan="5"><b> Remarks : </b> {{ grn.remarks }}</td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>
            </div>

            <div class="col-12 text-end mt-2 my-2">
              <form
                v-if="user_permissions.includes('is_md') && !grn.remarks"
                @submit.prevent="addRemark(grn_id)"
              >
                <div class="input-group my-2">
                  <input
                    type="text"
                    class="form-control"
                    placeholder="Enter Remarks"
                    v-model="remarks"
                  />
                  <button type="submit" class="btn btn-primary" :disabled="sending">
                    <span v-if="sending" v-html="loadingSpinner()"></span>
                    <span v-else>Send</span>
                  </button>
                </div>
              </form>
            </div>

            <div
              v-if="
                (receiver === 'No Receiver' || items.some((item) => item.shortage > 0)) &&
                user_permissions.includes('can_fill_grn')
              "
              class="row"
            >
              <div class="col-md-3 my-2">
                <Multiselect
                  v-model="store"
                  :options="stores"
                  :close-on-select="true"
                  label="name"
                  value-prop="id"
                  placeholder="Select Store"
                  :searchable="true"
                  class="w-100"
                />
              </div>
              <div class="col-md-2 my-2">
                <input type="date" class="form-control" v-model="date" />
              </div>
              <div class="col-md-7 my-2">
                <input
                  type="text"
                  class="form-control"
                  placeholder="Enter Brief Description"
                  v-model="description"
                />
              </div>
              <div class="col-12 text-end my-2">
                <form
                  v-if="
                    receiver === 'No Receiver' || items.some((item) => item.shortage > 0)
                  "
                  @submit.prevent="addRemark(grn_id, grn.project_id)"
                >
                  <button
                    type="submit"
                    class="btn btn-info btn-sm px-3"
                    :disabled="sending || !store"
                  >
                    <div v-if="sending" class="spinner-border text-white" role="status">
                      <span class="sr-only"></span>
                    </div>
                    <svg
                      v-else
                      xmlns="http://www.w3.org/2000/svg"
                      width="16"
                      height="16"
                      fill="currentColor"
                      class="bi bi-send-check"
                      viewBox="0 0 16 16"
                    >
                      <path
                        d="M15.964.686a.5.5 0 0 0-.65-.65L.767 5.855a.75.75 0 0 0-.124 1.329l4.995 3.178 1.531 2.406a.5.5 0 0 0 .844-.536L6.637 10.07l7.494-7.494-1.895 4.738a.5.5 0 1 0 .928.372zm-2.54 1.183L5.93 9.363 1.591 6.602z"
                      />
                      <path
                        d="M16 12.5a3.5 3.5 0 1 1-7 0 3.5 3.5 0 0 1 7 0m-1.993-1.679a.5.5 0 0 0-.686.172l-1.17 1.95-.547-.547a.5.5 0 0 0-.708.708l.774.773a.75.75 0 0 0 1.174-.144l1.335-2.226a.5.5 0 0 0-.172-.686"
                      />
                    </svg>
                  </button>
                </form>
              </div>
            </div>

            <!-- items table starts -->
            <div class="row layout-top-spacing">
              <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                  <!-- Remove table-responsive to prevent scroll -->
                  <div class="custom-table table3">
                    <table class="table table-striped table-bordered">
                      <thead>
                        <tr>
                          <th>SNo</th>
                          <th>Item</th>
                          <th>Description</th>
                          <th>vendor</th>
                          <th v-if="store">Bind To</th>
                          <th>Unit</th>
                          <th>Purchased</th>
                          <th style="min-width: 220px">Received</th>
                          <th>Shortage</th>
                        </tr>
                      </thead>
                      <tbody>
                        <tr v-for="(item, index) in items" :key="item.id">
                          <td>{{ index + 1 }}</td>
                          <td>{{ item.item }}</td>
                          <td>{{ item.description }}</td>
                          <td>{{ item.vendor }}</td>

                          <!-- Bind To column — has Multiselect inputs -->
                          <td
                            v-if="store.id > 0 && item.shortage > 0"
                            style="min-width: 450px; width: 450px"
                          >
                            <Multiselect
                              v-model="item.item_list_id"
                              :options="itemsList"
                              placeholder="Select Item"
                              label="name"
                              :close-on-select="true"
                              :searchable="true"
                              class="w-100"
                            />
                          </td>
                          <td
                            v-else-if="store.id == 0 && item.shortage > 0"
                            style="min-width: 450px; width: 450px"
                          >
                            <Multiselect
                              v-model="item.item_list_id"
                              :options="assets"
                              placeholder="Select An Asset"
                              label="name"
                              :close-on-select="true"
                              :searchable="true"
                              class="w-100"
                            />
                          </td>
                          <td
                            v-else-if="store.id == -1 && item.shortage > 0"
                            style="min-width: 450px; width: 450px"
                          >
                            <Multiselect
                              v-model="item.item_list_id"
                              :options="budgets"
                              placeholder="Select A Budget"
                              label="name"
                              :close-on-select="true"
                              :searchable="true"
                              class="w-100"
                            />
                          </td>
                          <td
                            v-else-if="store.id == -2 && item.shortage > 0"
                            style="min-width: 450px; width: 450px"
                          >
                            <span class="form-control-plaintext">{{ item.item }}</span>
                          </td>
                          <td
                            v-else-if="store && item.shortage == 0"
                            style="min-width: 450px; width: 450px"
                          ></td>

                          <td>{{ item.unit }}</td>
                          <td>{{ item.purchased }}</td>

                          <!-- Received column — has number inputs -->
                          <td style="min-width: 220px; width: 220px">
                            <span v-if="store && item.shortage > 0">
                              <input
                                v-if="item.item_list_id && item.item_list_id.id != 0"
                                type="number"
                                class="form-control w-100"
                                placeholder="Qty Received"
                                v-model="item.filled"
                                @input="
                                  item.filled = enforceMax(item.filled, item.shortage)
                                "
                              />
                              <input
                                v-if="item.item_list_id && item.item_list_id.id == 0"
                                type="number"
                                class="form-control w-100"
                                placeholder="Qty Returned"
                                v-model="item.filled"
                                @input="
                                  item.filled = enforceMax(item.filled, item.shortage)
                                "
                              />
                              <template v-if="store.id == 0">
                                <small
                                  v-if="item.item_list_id"
                                  class="text-muted d-block mb-1"
                                >
                                  Previous Reading:
                                  <strong>
                                    {{
                                      item.item_list_id.current_odometer_reading != null
                                        ? item.item_list_id.current_odometer_reading
                                        : "--"
                                    }}
                                  </strong>
                                </small>
                                <input
                                  type="number"
                                  placeholder="New Odometer Reading"
                                  class="form-control mt-1"
                                  v-model="item.initial_reading"
                                  :min="item.item_list_id?.current_odometer_reading ?? 0"
                                />
                              </template>
                            </span>
                            <span v-else>
                              <span v-if="item.returned_quantity > 0">
                                <span class="text-muted text-decoration-line-through">{{
                                  item.purchased
                                }}</span>
                                <span class="text-danger ms-2"
                                  >Returned: {{ item.returned_quantity }}</span
                                >
                              </span>
                              <span v-else>{{ item.received }}</span>
                            </span>
                          </td>

                          <td>{{ item.shortage }}</td>
                        </tr>
                        <tr v-for="(item, index) in items" :key="item.id">
                          <td
                            colspan="8"
                            class="bg-white text-success"
                            v-if="item.returned_quantity > 0"
                          >
                            <strong>Remark:</strong>
                            <i
                              >Returned Quantity : {{ item.returned_quantity }} @
                              {{ formatNumber(item.rate) }}</i
                            >
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            </div>

            <!-- items table ends -->
          </div>
          <div class="modal-footer">
            <button type="button" class="btn btn-secondary" @click="clearForm">
              Close
            </button>
          </div>
        </div>
      </div>
    </div>

    <!-- send message modal starts -->

    <!-- Modal -->
    <div
      class="modal fade"
      id="send_message"
      data-bs-backdrop="static"
      data-bs-keyboard="false"
      tabindex="-1"
      aria-labelledby="staticBackdropLabel"
      aria-hidden="true"
    >
      <div class="modal-dialog">
        <div class="modal-content">
          <div class="modal-header">
            <h1 class="modal-title fs-5" id="staticBackdropLabel">Send Report To :</h1>
            <button
              type="button"
              class="btn-close"
              data-bs-dismiss="modal"
              aria-label="Close"
              id="close_report"
              @click="clearForm"
            ></button>
          </div>
          <div class="modal-body">
            <input
              type="number"
              class="form-control"
              v-model="phone"
              placeholder="Send to : 255..."
            />
          </div>
          <div class="modal-footer">
            <button
              type="button"
              class="btn btn-danger btn-sm py-2 px-2"
              data-bs-dismiss="modal"
            >
              Close
            </button>
            <button
              type="button"
              @click="sendTemplate()"
              class="btn btn-success py-2 px-2"
            >
              <div v-if="sending" class="spinner-border text-white" role="status">
                <span class="sr-only"></span>
              </div>
              <svg
                v-else
                xmlns="http://www.w3.org/2000/svg"
                width="2"
                height="2"
                fill="currentColor"
                class="bi bi-send-check"
                viewBox="0 0 16 16"
              >
                <path
                  d="M15.964.686a.5.5 0 0 0-.65-.65L.767 5.855a.75.75 0 0 0-.124 1.329l4.995 3.178 1.531 2.406a.5.5 0 0 0 .844-.536L6.637 10.07l7.494-7.494-1.895 4.738a.5.5 0 1 0 .928.372zm-2.54 1.183L5.93 9.363 1.591 6.602z"
                />
                <path
                  d="M16 12.5a3.5 3.5 0 1 1-7 0 3.5 3.5 0 0 1 7 0m-1.993-1.679a.5.5 0 0 0-.686.172l-1.17 1.95-.547-.547a.5.5 0 0 0-.708.708l.774.773a.75.75 0 0 0 1.174-.144l1.335-2.226a.5.5 0 0 0-.172-.686"
                />
              </svg>
            </button>
          </div>
        </div>
      </div>
    </div>
    <!-- send messge modal ends -->
    <!-- register local order starts -->
    <div
      class="modal fade mymodal"
      id="register"
      data-bs-backdrop="false"
      data-bs-keyboard="false"
      tabindex="-1"
      aria-labelledby="staticBackdropLabel"
      aria-hidden="true"
    >
      <div class="modal-dialog modal-xl">
        <div class="modal-content">
          <div class="modal-header">
            <h1 class="modal-title fs-5" id="staticBackdropLabel">
              REGISTER LOCAL ORDER OUT OF ERP
            </h1>
            <button
              type="button"
              class="btn-close"
              data-bs-dismiss="modal"
              aria-label="Close"
              id="close-local-order"
            ></button>
          </div>
          <form @submit.prevent="registerLocalOrder()">
            <div class="modal-body">
              <div class="row layout-top-spacing">
                <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                  <div class="panel p-0">
                    <div class="custom-table table3">
                      <div class="row">
                        <h6 class="mt-2 mb-2">Order Details</h6>
                        <div class="col-md-4">
                          <label class="form-label">Source</label>
                          <select v-model="order.source" class="form-control" required>
                            <option value="">Select Reference Source</option>
                            <option value="ERP Voucher">ERP Voucher</option>
                            <option value="Local Voucher Paper">ERP Voucher</option>
                            <option value="Local Voucher">Local Voucher</option>
                            <option value="Local Order Paper">Local Order Paper</option>
                          </select>
                        </div>

                        <div v-if="order.source" class="col-md-4">
                          <label class="form-label">{{ order.source }} Number </label>
                          <input
                            class="form-control"
                            type="number"
                            step="any"
                            :placeholder="'Enter ' + order.source + ' Number'"
                            v-model="order.source_id"
                            required
                          />
                        </div>
                        <div v-if="order.source" class="col-md-4">
                          <label class="form-label">Select Project</label>
                          <Multiselect
                            v-model="order.project"
                            :options="projects"
                            :close-on-select="true"
                            label="short_name"
                            placeholder="Select Project"
                            :searchable="true"
                            class="w-100"
                          />
                        </div>

                        <div class="col-md-12">
                          <label class="form-label">Brief Description</label>
                          <input
                            class="form-control"
                            type="text"
                            placeholder="Enter Brief Description"
                            v-model="order.description"
                          />
                        </div>
                        <hr />
                        <div v-if="order.source_id">
                          <h6>Purchased Items</h6>
                          <div class="row">
                            <div class="col-md-3">
                              <label class="form-label">Item </label>
                              <input
                                class="form-control"
                                type="text"
                                placeholder="Enter Item"
                                v-model="orderItem.item"
                              />
