};

const fetchLocalOrders = async () => {
  loading_spinner.value = true;
  try {
    const response = await axiosInstance.get("local-orders");
    localOrders.value = response.data.map((item, index) => ({
      ...item,
      SNo: index + 1,
      source_id: item.local_order_no,
      project: item?.project?.short_name ?? "no Project",
      registrar: item.registrar.name,
      date: formatDate(item.created_at),
      delay: (() => {
        const created = new Date(item.created_at);
        const today = new Date();
        const createdUTC = Date.UTC(
          created.getFullYear(),
          created.getMonth(),
          created.getDate()
        );
        const todayUTC = Date.UTC(today.getFullYear(), today.getMonth(), today.getDate());
        const diffDays = Math.floor((todayUTC - createdUTC) / (1000 * 60 * 60 * 24));
        return diffDays > 3 ? diffDays - 3 : 0;
      })(),
    }));
  } catch (error) {
    console.log(error);
    showError(error.message);
  } finally {
    loading_spinner.value = false;
  }
};

const units = ref([]);
const getUnits = async () => {
  try {
    const response = await axiosInstance.get("units");
    units.value = response.data;
  } catch (error) {
    console.log(error);
    showError(error.message);
  }
};

const local_orders = ref(false);
const getLocalOrders = async () => {
  local_orders.value = !local_orders.value;
  if (local_orders.value == true) {
    fetchLocalOrders();
