    source: "",
    source_id: "",
    registrar_id: "",
    description: "",
    project: "",
  };
};

const registerLocalOrder = async () => {
  sending.value = true;
  const payload = {
    order: {
      source: order.value.source,
      local_order_no: order.value.source_id,
      registrar_id: JSON.parse(localStorage.getItem("user")).id,
