    items: orderedItems.value,
  };

  if (orderedItems.value.length === 0) {
    showError("Fill in atleast one item");
    sending.value = false;
    return;
  }

  try {
    const response = await axiosInstance.post("local-orders", payload);
    showMessage("Order Saved");
    fetchLocalOrders();
    clearOrderForm();
    document.getElementById("close-local-order").click();
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    sending.value = false;
