};

const orderedItems = ref([]);
const orderedItemColumns = ref([
  "Sno",
  "item",
  "description",
  "unit",
  "quantity",
  "actions",
]);
const i = ref(1);
const pushItem = () => {
  if (
    orderItem.value.quantity === "" ||
    orderItem.value.item === "" ||
    orderItem.value.unit === ""
  ) {
    showError("Fill required items");
    return;
  }
  const payload = {
    Sno: i.value,
    item: orderItem.value.item,
    description: orderItem.value.description,
    quantity: orderItem.value.quantity,
    unit: orderItem.value.unit.short_name,
  };
  orderedItems.value.push(payload);
  orderItem.value = {
    name: "",
    description: "",
    quantity: "",
    unit: "",
  };
  i.value = i.value + 1;
};

const pullItem = (sno) => {
  orderedItems.value = orderedItems.value.filter((item) => item.Sno !== sno);
  orderedItems.value.forEach((item, idx) => {
    item.Sno = idx + 1;
  });
  i.value = orderedItems.value.length + 1;
};

const sending = ref(false);
const tableShimmer = inject("tableShimmer");
const user = JSON.parse(localStorage.getItem("user"));
const reporting = ref(false);
const receiver_remarks = ref("");
const remarks_original = ref("");
const loading_spinner = ref(false);
const columns = ref([
  "SNo",
  "grn_no",
  "lpo_no",
  "project",
  "requester",
  "receiver",
  "cost",
  "briefing",
  "remarks",
