    count: "Showing {from} to {to} of {count}",
    filter: "",
    filterPlaceholder: "Search...",
    limit: "Results:",
  },
  resizableColumns: false,
});

const stores = ref([]);

const edit = ref("");
const phone = ref();

const clearForm = () => {
  document.getElementById("dismiss").click();
  document.getElementById("close-local-grn").click();
  document.getElementById("close_report").click();
  (receiver.value = ""), (description.value = ""), (remarks_original.value = "");
  reporting.value = false;
  phone.value = "";
  sending.value = false;
  edit.value = "";
  store.value = "";
  remarks.value = "";
  from_date.value = "";
to_date.value = "";
};

const items = ref([]);
const receiver = ref("");
const grn_id = ref(0);
const received_date = ref("");
const grn = ref("");

const selectedProjectId = ref(null);
const fillModal = (row) => {
  selectedProjectId.value = row.project_id;
  grn.value = row;
  grn_id.value = row.id;
  receiver_remarks.value = row.remarks_original;
  remarks_original.value = row.remarks_original;
  receiver.value = row.receiver;
  received_date.value = row.received_date;

  const approvalDate = new Date(row.approval?.created_at);
  const filterDate = new Date("2025-10-19");

  let itemsList = row.approval?.items || [];

  if (approvalDate >= filterDate) {
    itemsList = itemsList.filter((item) => item.requisition_items?.vendor_id);
  }

  items.value = itemsList.map((data, index) => {
    const receivedQty = Array.isArray(data.grn_items)
      ? data.grn_items.reduce((sum, gi) => sum + (parseFloat(gi.quantity) || 0), 0)
      : parseFloat(data.grn_item?.quantity) || 0;

    return {
      SNo: index + 1,
      id: data.id,
      asset_id: data.asset_id,
      unit: data.requisition_items?.units,
      rate: data.requisition_items?.rate ?? 0,
      vendor: data.requisition_items?.vendor?.name ?? "---",
      expected: data.quantity ?? "",
      item: data.requisition_items?.remark,
      description: data.requisition_items?.description,
      excess: data.grn_item?.excess ?? "",
      grn_item_id: data.grn_item?.id ?? 0,
      shortage: data.grn_item?.shortage ?? 0,
      item_list_id: 0,
      item_id: data.grn_item?.item_id ?? 2025,
      purchased: data.quantity ?? 0,
      received: receivedQty,
      quantity: data.quantity,
      shortage: (data.quantity - receivedQty).toFixed(2),
      filled: "",
      initial_reading: "",
      final_reading: "",
      returned_quantity:
        data.grn_items
          ?.filter((gi) => gi.status_id === 42)
          .reduce((sum, gi) => sum + (parseFloat(gi.quantity) || 0), 0) ?? 0,
    };
  });

  // Add vendor information to grn object
  // Get unique vendors from items
  const vendors = [
    ...new Set(
      itemsList
        .map((item) => item.requisition_items?.vendor?.name)
        .filter((vendor) => vendor)
    ),
  ];

  grn.value.vendor = vendors.length > 0 ? vendors.join(", ") : "No vendor";
};

const selectedOrder = ref("");
const fillLocalOrderModal = (row) => {
  selectedOrder.value = row;
  orderedItems.value = row.items.map((item, index) => ({
    ...item,
    Sno: index + 1,
    filled: "",
  }));
};

const receiveLocalOrder = async () => {
  sending.value = true;
  const remarkData = {
    user_id: JSON.parse(localStorage.getItem("user")).id,
    description: description.value,
    local_order_id: selectedOrder.value.id,
  };

  const grnItemData = orderedItems.value
    .map((item) => ({
      item_id: item.item_list_id?.id ?? item.item_id,
      order_item_id: item.id,
      quantity: item.filled,
      description: description.value,
    }))
    .filter((item) => item.item_id && item.quantity && item.quantity > 0);

  const storeItemData = orderedItems.value
    .map((item) => ({
      item_id: item.item_list_id?.id,
      quantity: item.filled,
      store_id: store.value.id,
      item_condition: "new",
    }))
    .filter((item) => item.item_id && item.quantity && item.quantity > 0);

  const payload = {
    remarkData,
    grnItemData,
    storeItemData,
  };

  try {
    const response = await axiosInstance.post(`/local-grns`, payload);
    await getGrns();
    showMessage("Receive Note Sent!");
    fetchLocalOrders();
    clearForm();
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    sending.value = false;
  }
};

const remarks = ref("");
const description = ref("");
const addRemark = async (id, project_id) => {
  sending.value = true;

  // Check if no data has been filled
  const hasFilledItems = items.value.some((item) => item.filled && item.filled > 0);

  if (!hasFilledItems) {
    showError("Fill required items.");
    sending.value = false;
    return;
  }

  // Check odometer readings when store is DIRECT TO ASSET
  if (store.value.id === 0) {
    const invalidReading = items.value.find(
      (item) =>
        item.filled > 0 &&
        item.item_list_id?.current_odometer_reading != null &&
        Number(item.initial_reading) < Number(item.item_list_id.current_odometer_reading)
    );

    if (invalidReading) {
      showError(`current reading can not be less than previous reading `);
      sending.value = false;
      return;
    }
  }

  const remarkData = {
    ...(remarks.value ? { remarks: remarks.value } : {}),
    description: description.value,
    date: date.value,
    user_id: user.id,
    project_id: project_id,
  };

  const storeItemData = items.value
    .map((item) => ({
      item_id: item.item_list_id?.id,
      quantity: item.filled,
      store_id: store.value.id,
      item_condition: "new",
      grn_item_id: item.grn_item_id,
      initial_reading: item.initial_reading,
      final_reading: item.final_reading,
      rate: item.rate,
       ...(store.value.id === -1 ? { type: store.value.type } : {}),
    }))
    .filter((item) => item.item_id && item.quantity);

  if (store.value.id === 0) {
    const missingReading = storeItemData.find(
      (item) => !item.initial_reading || item.initial_reading === 0
    );

    if (missingReading) {
      showError("Current odometer reading is required.");
      sending.value = false;
      return;
    }
  }

  const grnItemData = items.value
    .map((item) => ({
      item_id:
        item.item_list_id?.id === 0 ? item.id : item.item_list_id?.id ?? item.item_id,
      grn_id: id,
      ...(item.item_list_id?.id == 0 && { status_id: 42 }),
      approval_item_id: item.id,
      shortage: item.shortage ?? 0,
      quantity: item.filled,
      rate: item.rate,
      description: description.value,
      receiver_id: JSON.parse(localStorage.getItem("user")).id,
    }))
    .filter((item) => item.item_id && item.quantity);

  const bulkData = {
    remarkData,
    storeItemData,
    grnItemData,
  };

  try {
    const response = await axiosInstance.put(`/good-received-notes/${id}`, bulkData);
    await getGrns();
    showMessage("Receive Note Sent!");
    clearForm();
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    sending.value = false;
  }
};

const date = ref("");
const lpo_no = ref("");
const grn_cost = ref(0);
const from_date = ref("");
const to_date = ref("");
const project = ref('');

const getGrns = async () => {
  loading_spinner.value = true;
  grn_cost.value = 0;

  try {
    const params = new URLSearchParams();

    if (lpo_no.value) {
      params.append("approval_list_id", lpo_no.value);
    }

    if (grn_no.value) {
      params.append("grn_id", grn_no.value);
    }

    if (project.value && project.value.id) {
      params.append("project_id", project.value.id);
    }
    if (from_date.value && to_date.value) {
      params.append("from_date", from_date.value);
      params.append("to_date", to_date.value);
    }  if (selectedStatus.value) {
      params.append("status", selectedStatus.value);
    }

    const url = `good-received-notes${params.toString() ? "?" + params.toString() : ""}`;

    const response = await axiosInstance.get(url);

    let totalCost = 0;

    grns.value = response?.data.map((item, index) => {
      const itemCost = item.approval.items.reduce((total, i) => {
        return (
          total + parseFloat(i.quantity) * parseFloat(i.requisition_items?.rate ?? 0)
        );
      }, 0);

      totalCost += itemCost;

      const createdAt = new Date(item.created_at);
      const today = new Date();

      const diffDays = Math.floor(
        (today.setHours(0, 0, 0, 0) - createdAt.setHours(0, 0, 0, 0)) /
          (1000 * 60 * 60 * 24)
      );

      const pendingQty = item.approval.items.reduce((total, i) => {
        const purchased = parseFloat(i.quantity) || 0;
        const received = Array.isArray(i.grn_items)
          ? i.grn_items.reduce((sum, gi) => sum + (parseFloat(gi.quantity) || 0), 0)
          : parseFloat(i.grn_items?.quantity) || 0;

        return total + (purchased - received);
      }, 0);

      let statusKey = "";
      let statusClass = "";
      let delayedCount = "--";

      if (item?.receiver?.name) {
        if (pendingQty > 0) {
          statusKey = "Partial Received";
          statusClass = "secondary";
        } else {
          statusKey = "Received";
          statusClass = "success";
        }
      } else if (diffDays <= 3) {
        statusKey = "Pending";
        statusClass = "warning";
      } else {
        statusKey = "Delayed";
        statusClass = "danger";
        delayedCount = diffDays - 3;
      }

      return {
        ...item,
        SNo: index + 1,
        id: item.id,
        briefing: item.approval.requisition.description,
        project: item.approval.requisition.project?.short_name ?? "no project",
        project_id: item.approval.requisition.project?.id ?? "",
        requester: item.approval?.requester?.name ?? "Unknown",
        lpo_no: "0" + item.approval_list_id,
        approval_id: item.approval_list_id,
        receiver: item?.receiver?.name ?? "---",
        grn_no: item.id,
        remarks: item.remarks,
        remarks_original: item.remarks ?? "",
        status: { key: statusKey, class: statusClass },
        delay: delayedCount ?? "--",
        date: formatDate(item.created_at),
        received_date: formatDate(item.date),
        cost: formatNumber(itemCost),
        pending: pendingQty.toFixed(2),
      };
    });

    grn_cost.value = totalCost;
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    loading_spinner.value = false;
  }
};


const budgets = ref([]);
const isBudgetsloading = ref(false);

const getBudgets = async (id) => {
  isBudgetsloading.value = true;
  budgets.value = [];

  try {
    const response = await axiosInstance.get(`get-budgets?project_id=${id}`);

    const realBudgets = response.data.filter(
      (b) => b.status === "closed"
    );

    const generalBudget = {
      id: null,
      name: "General",
    };

    budgets.value = [generalBudget, ...realBudgets];

  } catch (error) {
    console.log(error);
    showError(error.message);
  } finally {
    isBudgetsloading.value = false;
  }
};

watch(store, (newVal) => {
  if (newVal && newVal.id === -1) {
    getBudgets(selectedProjectId.value);
  }
});

watch(lpo_no, (newVal) => {
  if (newVal) {
    getGrns();
  }
});

const grn_no = ref("");
watch(grn_no, (newVal) => {
  if (newVal) {
    getGrns();
  }
});

const suppressDateWatch = ref(false);

watch([from_date, to_date], async ([newFromDate, newToDate]) => {
  if (suppressDateWatch.value) return;

  if (newFromDate && newToDate) {
    lpo_no.value = "";
    grn_no.value = "";
    await getGrns();
  }
});


const status = ref("");
const statuses = ref([
  {
    id: 1,
    name: "Received",
  },
  {
    id: 2,
    name: "Pending",
  },
  {
    id: 3,
    name: "Partial Received",
  },
  {
    id: 4,
    name: "Delayed",
  },
]);

const selectedStatus = ref("");
const handleStatusChange = async (status) => {
  suppressDateWatch.value = true;
  date.value = "";
  await nextTick();
  suppressDateWatch.value = false;
  selectedStatus.value = status.name;
  await getGrns();
};

const handlePrintReport = () => {
  printGrnsReport(grns.value, selectedStatus.value, date.value, formatNumber, showError);
};

const handleExcelReport = () => {
  exportGrnsReportToExcel(grns.value, selectedStatus.value, date.value, formatNumber, showError);
};

const getFormData = async () => {
  try {
    const response = await axiosInstance.get("grn-form-data");
    const {
      stores: storesData,
      item_list: itemsData,
      machines: machinesData,
    } = response.data;

    stores.value = [
      { id: 0, name: "DIRECT TO ASSET" },
       { id: -1, name: "BULK DIESEL", type: "DIESEL" },
       { id: -1, name: "BULK PETROL", type: "PETROL" },
      ...storesData.map((item) => ({
        ...item,
        name: item.project + " - " + item.name,
      })),
    ];

    itemsList.value = [
      { id: 0, name: "Returned" },
      ...itemsData.map((item) => ({
        ...item,
        name: item.name + (item.description ? " - " + item.description : ""),
      })),
    ];

    assets.value = machinesData.map((item) => ({
      ...item,
      name: item.name + " - " + item.type_name,
    }));
  } catch (error) {
    console.log(error);
    showError(error.message);
  }
};

watch(project, (newVal) => {
  getGrns();
});



onMounted(() => {
  loading_spinner.value = true;
  getGrns();
  getProjects();
  getFormData();
});
